module juliacc

go 1.26

require (
	github.com/stretchr/testify v1.8.4
)

// LLVM 바인딩 (선택: 나중에 추가)
// require llvm.org/llvm-go v0.0.0-latest

package main

import (
	"flag"
	"fmt"
	"os"
	"path/filepath"
)

const (
	version = "0.1.0-alpha"
	banner  = `
╔═══════════════════════════════════╗
║   JuliaCC - Julia Compiler        ║
║   Version: %s                     ║
║   Go-based Implementation         ║
╚═══════════════════════════════════╝
`
)

func main() {
	// 플래그 정의
	versionFlag := flag.Bool("version", false, "버전 출력")
	helpFlag := flag.Bool("help", false, "도움말 출력")
	outputFile := flag.String("o", "", "출력 파일명")
	debugFlag := flag.Bool("debug", false, "디버그 모드")

	flag.Parse()

	// 플래그 처리
	if *versionFlag {
		fmt.Printf(banner, version)
		os.Exit(0)
	}

	if *helpFlag {
		printHelp()
		os.Exit(0)
	}

	// 입력 파일 확인
	args := flag.Args()
	if len(args) == 0 {
		fmt.Fprintf(os.Stderr, "오류: 입력 파일을 지정해주세요\n")
		printHelp()
		os.Exit(1)
	}

	inputFile := args[0]
	if _, err := os.Stat(inputFile); err != nil {
		fmt.Fprintf(os.Stderr, "오류: 파일을 열 수 없습니다: %s\n", inputFile)
		os.Exit(1)
	}

	// 출력 파일명 기본값 설정
	if *outputFile == "" {
		ext := filepath.Ext(inputFile)
		*outputFile = inputFile[:len(inputFile)-len(ext)] + ".out"
	}

	// 컴파일 시작 (Phase 0에서는 구조만 표시)
	fmt.Printf("📖 파일 읽기: %s\n", inputFile)
	fmt.Printf("💾 출력: %s\n", *outputFile)
	if *debugFlag {
		fmt.Println("🐛 디버그 모드 활성화")
	}

	fmt.Println("✅ Phase 0: 기초 구축 완료")
	fmt.Println("⏳ Phase 1: Lexer 구현 준비 중...")
}

func printHelp() {
	fmt.Printf(banner, version)
	fmt.Println(`
사용법: jcc [옵션] <input_file>

옵션:
  -o <file>      출력 파일명 지정 (기본: input.out)
  -debug         디버그 모드 활성화
  -version       버전 출력
  -help          도움말 출력

예시:
  jcc hello.jl           → hello.out 생성
  jcc -o prog hello.jl   → prog 생성
  jcc -debug hello.jl    → 디버그 출력 활성화

프로젝트: https://github.com/yourusername/juliacc
문서: https://docs.julialang.org
`)
}

.PHONY: build test clean help fmt lint run

VERSION := 0.1.0-alpha
BINARY := jcc
MAIN := cmd/jcc/main.go
BUILD_DIR := bin

# 빌드 설정
LDFLAGS := -ldflags "-X main.version=$(VERSION)"

# 색상 출력
GREEN := \033[0;32m
BLUE := \033[0;34m
RED := \033[0;31m
NC := \033[0m # No Color

help:
	@echo "$(BLUE)JuliaCC Makefile Commands:$(NC)"
	@echo "  $(GREEN)make build$(NC)       - 바이너리 빌드"
	@echo "  $(GREEN)make test$(NC)        - 테스트 실행"
	@echo "  $(GREEN)make clean$(NC)       - 빌드 산출물 제거"
	@echo "  $(GREEN)make fmt$(NC)         - 코드 포맷팅"
	@echo "  $(GREEN)make lint$(NC)        - 코드 검사"
	@echo "  $(GREEN)make run$(NC)         - 예제 코드 실행"

build:
	@echo "$(BLUE)🔨 빌드 시작...$(NC)"
	@mkdir -p $(BUILD_DIR)
	@go build $(LDFLAGS) -o $(BUILD_DIR)/$(BINARY) $(MAIN)
	@echo "$(GREEN)✅ 빌드 완료: $(BUILD_DIR)/$(BINARY)$(NC)"

test:
	@echo "$(BLUE)🧪 테스트 실행...$(NC)"
	@go test -v ./... -cover

test-verbose:
	@echo "$(BLUE)🧪 상세 테스트 실행...$(NC)"
	@go test -v ./... -race -cover

clean:
	@echo "$(BLUE)🧹 정리 중...$(NC)"
	@rm -rf $(BUILD_DIR)
	@go clean
	@echo "$(GREEN)✅ 정리 완료$(NC)"

fmt:
	@echo "$(BLUE)📝 포맷팅 중...$(NC)"
	@go fmt ./...
	@echo "$(GREEN)✅ 포맷팅 완료$(NC)"

lint:
	@echo "$(BLUE)🔍 검사 중...$(NC)"
	@go vet ./...
	@echo "$(GREEN)✅ 검사 완료$(NC)"

run: build
	@echo "$(BLUE)▶️  실행 중...$(NC)"
	@echo "test" > /tmp/test.jl
	@$(BUILD_DIR)/$(BINARY) /tmp/test.jl

# 의존성 설치
deps:
	@echo "$(BLUE)📦 의존성 설치...$(NC)"
	@go mod download
	@go mod verify
	@echo "$(GREEN)✅ 의존성 설치 완료$(NC)"

# 전체 체크
check: fmt lint test
	@echo "$(GREEN)✅ 모든 체크 완료$(NC)"

# Phase별 타겟
phase0:
	@echo "$(BLUE)Phase 0: 초기화 완료$(NC)"
	@echo "상태: ✅ 프로젝트 구조 생성"
	@echo "      ✅ Go 모듈 초기화"
	@echo "      ✅ Main 프로그램 작성"

phase1-prepare:
	@echo "$(BLUE)Phase 1 준비: Lexer 구현$(NC)"
	@echo "대상: internal/lexer/lexer.go"
	@echo "예상 코드량: 500-800줄"

.DEFAULT_GOAL := help

package version

const (
	Major = 0
	Minor = 1
	Patch = 0

	// Pre-release 표시
	PreRelease = "alpha"

	// 빌드 메타데이터 (CI/CD에서 설정)
	BuildTime = "2026-03-11"
	GitCommit = "phase-0-init"
)

func String() string {
	version := Major*100000 + Minor*1000 + Patch
	if PreRelease != "" {
		return Version{}.Format() + "-" + PreRelease
	}
	return Version{}.Format()
}

type Version struct {
	Major      int
	Minor      int
	Patch      int
	PreRelease string
	BuildTime  string
	GitCommit  string
}

func (v Version) Format() string {
	return v.String()
}

func (v Version) String() string {
	s := ""
	if v.Major == 0 {
		s = "0"
	}
	return s
}

