package lexer

import (
	"testing"
)

// TestBasicTokens - 기본 토큰 테스트
func TestBasicTokens(t *testing.T) {
	tests := []struct {
		input    string
		expected []TokenType
	}{
		{
			input:    "x = 5",
			expected: []TokenType{TokenIdentifier, TokenEqual, TokenInteger, TokenEOF},
		},
		{
			input:    "sin(x) + 1.0",
			expected: []TokenType{TokenIdentifier, TokenLparen, TokenIdentifier, TokenRparen, TokenPlus, TokenFloat, TokenEOF},
		},
		{
			input:    "function add(a, b) return a + b end",
			expected: []TokenType{TokenKeywordFunction, TokenIdentifier, TokenLparen, TokenIdentifier, TokenComma, TokenIdentifier, TokenRparen, TokenKeywordReturn, TokenIdentifier, TokenPlus, TokenIdentifier, TokenKeywordEnd, TokenEOF},
		},
	}

	for _, tt := range tests {
		lexer := NewLexer(tt.input)
		for i, expected := range tt.expected {
			token := lexer.NextToken()
			if token.Type != expected {
				t.Errorf("Test %d: token %d expected %v, got %v", i, i, expected, token.Type)
			}
			if token.Type == TokenEOF {
				break
			}
		}
	}
}

// TestKeywords - 키워드 테스트
func TestKeywords(t *testing.T) {
	input := "if else for while function end"
	lexer := NewLexer(input)

	expected := []TokenType{
		TokenKeywordIf,
		TokenKeywordElse,
		TokenKeywordFor,
		TokenKeywordWhile,
		TokenKeywordFunction,
		TokenKeywordEnd,
		TokenEOF,
	}

	for _, exp := range expected {
		token := lexer.NextToken()
		if token.Type != exp {
			t.Errorf("Expected %v, got %v", exp, token.Type)
		}
		if token.Type == TokenEOF {
			break
		}
	}
}

// TestNumbers - 숫자 테스트
func TestNumbers(t *testing.T) {
	tests := []struct {
		input    string
		expected TokenType
	}{
		{"123", TokenInteger},
		{"123.456", TokenFloat},
		{"1e-10", TokenFloat},
		{"3.14159", TokenFloat},
	}

	for _, tt := range tests {
		lexer := NewLexer(tt.input)
		token := lexer.NextToken()
		if token.Type != tt.expected {
