	lexer := NewLexer(input)

	expected := []TokenType{
		TokenPlus,
		TokenMinus,
		TokenStar,
		TokenSlash,
		TokenEqualEqual,
		TokenNotEqual,
		TokenLess,
		TokenLessEqual,
		TokenGreater,
		TokenGreaterEqual,
		TokenAnd,
		TokenOr,
		TokenArrow,
		TokenEOF,
	}

	for _, exp := range expected {
		token := lexer.NextToken()
		if token.Type != exp {
			t.Errorf("Expected %v, got %v", exp, token.Type)
		}
		if token.Type == TokenEOF {
			break
		}
	}
}

// TestStrings - 문자열 테스트
func TestStrings(t *testing.T) {
	input := `"hello" 'world'`
	lexer := NewLexer(input)

	token := lexer.NextToken()
	if token.Type != TokenString {
		t.Errorf("Expected STRING, got %v", token.Type)
	}

	token = lexer.NextToken()
	if token.Type != TokenString {
		t.Errorf("Expected STRING, got %v", token.Type)
	}
}

