// 파일: internal/lexer/lexer.go
// 예상 코드량: 500-800줄

import (
	"fmt"
	"unicode"
)

// TokenType - 토큰 종류
type TokenType int

const (
	// 기본
	TokenEOF TokenType = iota
	TokenError
	TokenNewline

	// 키워드
	TokenKeywordFunction
	TokenKeywordIf
	TokenKeywordElse
	TokenKeywordElseif
