	TokenKeywordMutable
	TokenKeywordConst
	TokenKeywordLet
	TokenKeywordTrue
	TokenKeywordFalse
	TokenKeywordNothing

	// 리터럴
	TokenInteger
	TokenFloat
	TokenString
	TokenSymbol
	TokenIdentifier

	// 연산자
	TokenPlus      // +
	TokenMinus     // -
	TokenStar      // *
	TokenSlash     // /
	TokenPercent   // %
	TokenCaret     // ^
	TokenEqual     // =
	TokenEqualEqual // ==
	TokenNotEqual  // !=
	TokenLess      // <
	TokenLessEqual // <=
	TokenGreater   // >
	TokenGreaterEqual // >=
	TokenAnd       // &&
	TokenOr        // ||
	TokenNot       // !
	TokenDot       // .
	TokenDotDot    // ..
	TokenDoubleColon // ::
	TokenArrow     // ->
	TokenPipe      // |>

	// 괄호
	TokenLparen    // (
	TokenRparen    // )
	TokenLbrace    // {
	TokenRbrace    // }
	TokenLbracket  // [
	TokenRbracket  // ]

	// 구분자
	TokenComma
	TokenSemicolon
	TokenColon
	TokenAt        // @
)

// Token 구조체
type Token struct {
	Type   TokenType
	Lexeme string
	Line   int
	Column int
}

// Lexer 구조체
type Lexer struct {
	input  string
	pos    int  // 현재 위치
	line   int  // 현재 줄
	column int  // 현재 열
	ch     rune // 현재 문자
}

// NewLexer - 새로운 Lexer 생성
func NewLexer(input string) *Lexer {
	l := &Lexer{
		input:  input,
		pos:    0,
		line:   1,
		column: 0,
		ch:     rune(0),
	}
	l.readChar()
	return l
}

// readChar - 다음 문자 읽기
func (l *Lexer) readChar() {
	if l.pos >= len(l.input) {
		l.ch = rune(0)
	} else {
		l.ch = rune(l.input[l.pos])
	}
	l.pos++
	l.column++
}

// peekChar - 다음 문자 미리보기 (읽지 않음)
func (l *Lexer) peekChar() rune {
	if l.pos >= len(l.input) {
		return rune(0)
	}
	return rune(l.input[l.pos])
}

// NextToken - 다음 토큰 반환
func (l *Lexer) NextToken() Token {
	// 공백 건너뛰기
	for l.ch == ' ' || l.ch == '\t' || l.ch == '\r' {
		l.readChar()
	}

	line := l.line
	column := l.column

	// EOF
	if l.ch == rune(0) {
		return Token{Type: TokenEOF, Lexeme: "", Line: line, Column: column}
	}

	// 개행
	if l.ch == '\n' {
		l.readChar()
		l.line++
		l.column = 0
		return Token{Type: TokenNewline, Lexeme: "\n", Line: line, Column: column}
	}

	// 주석 (# ... 또는 #= ... =#)
	if l.ch == '#' {
		// TODO: 주석 처리
		return l.NextToken()
	}

	// 문자열
	if l.ch == '"' || l.ch == '\'' {
		return l.readString(line, column)
	}

	// 숫자
	if unicode.IsDigit(l.ch) {
		return l.readNumber(line, column)
	}

	// 식별자 또는 키워드
	if unicode.IsLetter(l.ch) || l.ch == '_' {
		return l.readIdentifier(line, column)
	}

	// 연산자 및 기타
	return l.readOperator(line, column)
}

// readString - 문자열 읽기
func (l *Lexer) readString(line, column int) Token {
	quote := l.ch
	l.readChar()
	start := l.pos - 1

	for l.ch != quote && l.ch != rune(0) {
		if l.ch == '\n' {
			l.line++
			l.column = 0
		}
		l.readChar()
	}

	lexeme := l.input[start : l.pos]
	if l.ch == quote {
		l.readChar()
	}

	return Token{Type: TokenString, Lexeme: lexeme, Line: line, Column: column}
}

// readNumber - 숫자 읽기
func (l *Lexer) readNumber(line, column int) Token {
	start := l.pos - 1

	for unicode.IsDigit(l.ch) {
		l.readChar()
	}

	// 부동소수점
	if l.ch == '.' && unicode.IsDigit(l.peekChar()) {
		l.readChar()
		for unicode.IsDigit(l.ch) {
			l.readChar()
		}
		return Token{Type: TokenFloat, Lexeme: l.input[start:l.pos], Line: line, Column: column}
	}

	// 지수 표기법 (e, E)
	if l.ch == 'e' || l.ch == 'E' {
		l.readChar()
		if l.ch == '+' || l.ch == '-' {
			l.readChar()
		}
		for unicode.IsDigit(l.ch) {
			l.readChar()
		}
		return Token{Type: TokenFloat, Lexeme: l.input[start:l.pos], Line: line, Column: column}
	}

	return Token{Type: TokenInteger, Lexeme: l.input[start:l.pos], Line: line, Column: column}
}

// readIdentifier - 식별자 읽기
func (l *Lexer) readIdentifier(line, column int) Token {
	start := l.pos - 1

	for unicode.IsLetter(l.ch) || unicode.IsDigit(l.ch) || l.ch == '_' {
		l.readChar()
	}

	lexeme := l.input[start:l.pos]

	// 키워드 검사
	tokenType := keywordOrIdentifier(lexeme)

	return Token{Type: tokenType, Lexeme: lexeme, Line: line, Column: column}
