package version

const (
	Major = 0
	Minor = 1
	Patch = 0

	// Pre-release 표시
	PreRelease = "alpha"

	// 빌드 메타데이터 (CI/CD에서 설정)
	BuildTime = "2026-03-11"
	GitCommit = "phase-0-init"
)

func String() string {
	version := Major*100000 + Minor*1000 + Patch
	if PreRelease != "" {
		return Version{}.Format() + "-" + PreRelease
	}
	return Version{}.Format()
}

type Version struct {
	Major      int
	Minor      int
	Patch      int
	PreRelease string
	BuildTime  string
	GitCommit  string
}

func (v Version) Format() string {
	return v.String()
}

func (v Version) String() string {
	s := ""
	if v.Major == 0 {
		s = "0"
	}
	return s
}

package main

import (
	"flag"
	"fmt"
	"os"
	"path/filepath"
)

const (
	version = "0.1.0-alpha"
	banner  = `
╔═══════════════════════════════════╗
║   JuliaCC - Julia Compiler        ║
║   Version: %s                     ║
║   Go-based Implementation         ║
╚═══════════════════════════════════╝
`
)

func main() {
	// 플래그 정의
	versionFlag := flag.Bool("version", false, "버전 출력")
	helpFlag := flag.Bool("help", false, "도움말 출력")
	outputFile := flag.String("o", "", "출력 파일명")
	debugFlag := flag.Bool("debug", false, "디버그 모드")

	flag.Parse()

	// 플래그 처리
	if *versionFlag {
		fmt.Printf(banner, version)
		os.Exit(0)
	}

	if *helpFlag {
		printHelp()
		os.Exit(0)
	}

	// 입력 파일 확인
	args := flag.Args()
	if len(args) == 0 {
		fmt.Fprintf(os.Stderr, "오류: 입력 파일을 지정해주세요\n")
		printHelp()
		os.Exit(1)
	}

	inputFile := args[0]
	if _, err := os.Stat(inputFile); err != nil {
		fmt.Fprintf(os.Stderr, "오류: 파일을 열 수 없습니다: %s\n", inputFile)
		os.Exit(1)
	}

	// 출력 파일명 기본값 설정
	if *outputFile == "" {
		ext := filepath.Ext(inputFile)
		*outputFile = inputFile[:len(inputFile)-len(ext)] + ".out"
	}

	// 컴파일 시작 (Phase 0에서는 구조만 표시)
	fmt.Printf("📖 파일 읽기: %s\n", inputFile)
	fmt.Printf("💾 출력: %s\n", *outputFile)
	if *debugFlag {
		fmt.Println("🐛 디버그 모드 활성화")
	}

	fmt.Println("✅ Phase 0: 기초 구축 완료")
	fmt.Println("⏳ Phase 1: Lexer 구현 준비 중...")
}

func printHelp() {
	fmt.Printf(banner, version)
	fmt.Println(`
사용법: jcc [옵션] <input_file>

옵션:
  -o <file>      출력 파일명 지정 (기본: input.out)
  -debug         디버그 모드 활성화
  -version       버전 출력
  -help          도움말 출력

예시:
  jcc hello.jl           → hello.out 생성
  jcc -o prog hello.jl   → prog 생성
  jcc -debug hello.jl    → 디버그 출력 활성화

프로젝트: https://github.com/yourusername/juliacc
문서: https://docs.julialang.org
`)
}

