// BenchmarkLexer - Lexer 성능 벤치마크
func BenchmarkLexer(b *testing.B) {
	input := `
	function fibonacci(n::Int)::Int
		if n <= 1
			return n
		else
			return fibonacci(n-1) + fibonacci(n-2)
		end
	end

