// TestPhase2TryStatement - Try-Catch 문
func TestPhase2TryStatement(t *testing.T) {
	input := `try
		risky_operation()
	catch e
		println(e)
	end`

	tokens := tokenize(input)
	p := NewParser(tokens)
	prog, err := p.Parse()

	if err != nil {
		t.Fatalf("파싱 에러: %v", err)
	}

	tryStmt, ok := prog.Statements[0].(*ast.TryStmt)
	if !ok {
		t.Fatalf("TryStmt가 아님: %T", prog.Statements[0])
	}

	if len(tryStmt.TryBody) == 0 {
		t.Error("try 블록이 비어있음")
	}

	if len(tryStmt.CatchClauses) != 1 {
		t.Errorf("catch 절 개수 예상: 1, 얻음: %d", len(tryStmt.CatchClauses))
	}
}

