// Phase 2: Parser - AST (추상 구문 트리) 노드 정의

import (
	"fmt"
	"juliacc/internal/lexer"
)

// Node - 모든 AST 노드의 기본 인터페이스
type Node interface {
	node()
}

// Expr - 표현식 노드
type Expr interface {
	Node
	expr()
}

// Stmt - 문(명령문) 노드
type Stmt interface {
	Node
	stmt()
}

// ============================================
// 표현식 노드 (Expr)
// ============================================

// Literal - 리터럴 (정수, 부동소수, 문자열, 심볼, true/false/nothing)
type Literal struct {
	Token lexer.Token
	Value interface{}
}

func (l *Literal) node() {}
func (l *Literal) expr() {}
func (l *Literal) String() string {
	return fmt.Sprintf("Literal(%v)", l.Value)
}

// Identifier - 식별자
type Identifier struct {
	Token lexer.Token
	Name  string
}

func (i *Identifier) node() {}
func (i *Identifier) expr() {}
func (i *Identifier) String() string {
	return i.Name
}

// BinaryOp - 이항 연산 (a + b, a * b, etc)
type BinaryOp struct {
	Left     Expr
	Op       lexer.TokenType
	Right    Expr
	OpToken  lexer.Token
}

func (b *BinaryOp) node() {}
func (b *BinaryOp) expr() {}
func (b *BinaryOp) String() string {
	return fmt.Sprintf("(%s %v %s)", b.Left, b.OpToken.Lexeme, b.Right)
}

// UnaryOp - 단항 연산 (!a, -a, ~a, etc)
type UnaryOp struct {
	Op      lexer.TokenType
	Operand Expr
	OpToken lexer.Token
}

func (u *UnaryOp) node() {}
func (u *UnaryOp) expr() {}
func (u *UnaryOp) String() string {
	return fmt.Sprintf("%s%s", u.OpToken.Lexeme, u.Operand)
}

// Call - 함수 호출 (f(a, b, c))
type Call struct {
	Function  Expr
	Arguments []Expr
	LParen    lexer.Token
	RParen    lexer.Token
}

func (c *Call) node() {}
func (c *Call) expr() {}
func (c *Call) String() string {
	return fmt.Sprintf("%s(...)", c.Function)
}

// Index - 인덱싱 (a[i], matrix[i,j])
type Index struct {
	Object Expr
	Index  []Expr
	LBracket lexer.Token
	RBracket lexer.Token
}

func (i *Index) node() {}
func (i *Index) expr() {}
func (i *Index) String() string {
	return fmt.Sprintf("%s[...]", i.Object)
}

// MemberAccess - 멤버 접근 (obj.field)
