	return fmt.Sprintf("%s::%s", t.Expr, t.Type)
}

// ArrayLiteral - 배열 리터럴 ([1, 2, 3], [a b; c d])
type ArrayLiteral struct {
	Elements [][]Expr // 2D for matrix support
	LBracket lexer.Token
	RBracket lexer.Token
}

func (a *ArrayLiteral) node() {}
