// 문(Statement) 노드 (Stmt)
// ============================================

// ExprStmt - 표현식 문 (3 + 4; x;)
type ExprStmt struct {
	Expr Expr
}

func (e *ExprStmt) node() {}
func (e *ExprStmt) stmt() {}
func (e *ExprStmt) String() string {
	return e.Expr.String()
}

