		t.Errorf("루트 연산자가 -가 아님: %v", binOp.Op)
	}

	leftBinOp, ok := binOp.Left.(*ast.BinaryOp)
	if !ok {
		t.Fatalf("왼쪽 자식이 BinaryOp가 아님: %T", binOp.Left)
	}

	if leftBinOp.Op != lexer.TokenPlus {
		t.Errorf("왼쪽 자식 연산자가 +가 아님: %v", leftBinOp.Op)
	}
}

