	if !ok {
		t.Fatalf("오른쪽 자식이 BinaryOp가 아님: %T", binOp.Right)
	}

	if rightBinOp.Op != lexer.TokenCaret {
		t.Errorf("오른쪽 자식 연산자가 ^가 아님: %v", rightBinOp.Op)
	}
}

