	for i in 1:100
		result = fibonacci(i)
		println(result)
	end

	struct Point{T <: Real}
		x::T
		y::T
	end

	function distance(p1::Point, p2::Point)::Float64
		return sqrt((p1.x - p2.x)^2 + (p1.y - p2.y)^2)
	end
	`

	b.ResetTimer()
	for i := 0; i < b.N; i++ {
		tokens := tokenize(input)
		p := NewParser(tokens)
		_, _ = p.Parse()
	}
}

